insert into public.boss_questions(id,class_id,chapter_id,lesson_id,question,options,correct_answer,hint,explanation,version) values('g6-3-10-11',6,3,10,'Thức ăn có nấm mốc cần được xử lý thế nào?','["Chỉ đổi tên rồi ăn","Không dùng và xử lý an toàn","Trộn với thực phẩm mới"]'::jsonb,1,'Một phần mốc nhìn thấy không phản ánh toàn bộ nguy cơ.','Không dùng và xử lý an toàn. Một phần mốc nhìn thấy không phản ánh toàn bộ nguy cơ.','g6-boss-2026.1') on conflict do nothing;
