insert into public.boss_questions(id,class_id,chapter_id,lesson_id,question,options,correct_answer,hint,explanation,version) values('g6-3-10-13',6,3,10,'Điều kiện ẩm có thể ảnh hưởng nấm mốc thế nào?','["Thuận lợi cho nhiều loại phát triển","Luôn diệt mọi loại nấm","Biến nấm thành động vật"]'::jsonb,0,'Liên hệ bảo quản đồ dùng và thực phẩm.','Thuận lợi cho nhiều loại phát triển. Liên hệ bảo quản đồ dùng và thực phẩm.','g6-boss-2026.1') on conflict do nothing;
insert into public.boss_questions(id,class_id,chapter_id,lesson_id,question,options,correct_answer,hint,explanation,version) values('g6-3-10-14',6,3,10,'Giữ đồ dùng sạch và khô giúp ích gì?','["Bảo đảm không có nấm ở mọi nơi","Hạn chế nấm phát triển trên đồ dùng","Làm nấm quang hợp"]'::jsonb,1,'Chọn tác dụng hợp lý của vệ sinh.','Hạn chế nấm phát triển trên đồ dùng. Chọn tác dụng hợp lý của vệ sinh.','g6-boss-2026.1') on conflict do nothing;
